/// Converts a memory keywords value to its keywords (eg. `dword ptr`)
constexpr FormatterStringSlice get_memory_keywords(const FormatterArrayConstants& ac, std::uint32_t memory_keywords) noexcept {
	switch (memory_keywords) {
	case 0x00: return ac.nothing;
	case 0x01: return ac.byte_ptr;
	case 0x02: return ac.dword_bcst;
	case 0x03: return ac.dword_ptr;
	case 0x04: return ac.fpuenv14_ptr;
	case 0x05: return ac.fpuenv28_ptr;
	case 0x06: return ac.fpustate108_ptr;
	case 0x07: return ac.fpustate94_ptr;
	case 0x08: return ac.fword_ptr;
	case 0x09: return ac.oword_ptr;
	case 0x0A: return ac.qword_bcst;
	case 0x0B: return ac.qword_ptr;
	case 0x0C: return ac.tbyte_ptr;
	case 0x0D: return ac.word_ptr;
	case 0x0E: return ac.xmmword_ptr;
	case 0x0F: return ac.ymmword_ptr;
	case 0x10: return ac.zmmword_ptr;
	case 0x11: return ac.mem384_ptr;
	case 0x12: return ac.word_bcst;
	default: ICED_UNREACHABLE();
	}
}

